#!/usr/bin/env python3
"""Turn third_party/ca-bundle/cacert.pem into a C include file for the Linux build."""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
pem = (root / "third_party/ca-bundle/cacert.pem").read_bytes()
if b"BEGIN CERTIFICATE" not in pem:
    raise SystemExit("cacert.pem does not look like a PEM bundle")

out = root / "src/platform/linux/ca_bundle_embedded.inc"
lines = [
    "// Generated by scripts/gen_ca_bundle.py from third_party/ca-bundle/cacert.pem.",
    "// Do not edit by hand.",
    f"static const unsigned char kEmbeddedCaBundle[{len(pem)}] = {{",
]
for i in range(0, len(pem), 20):
    lines.append("    " + ",".join(str(b) for b in pem[i:i + 20]) + ",")
lines.append("};")
lines.append(f"static const size_t kEmbeddedCaBundleCerts = {pem.count(b'BEGIN CERTIFICATE')};")
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out.relative_to(root)} ({len(pem)} bytes, {pem.count(b'BEGIN CERTIFICATE')} certs)")
